export function smallestRangeCoveringElementsFromKLists(lists            )           {
const events           =[];lists.forEach((row,i)=>row.forEach(v=>events.push([v,i])));events.sort((a,b)=>a[0]-b[0]);const counts=Array(lists.length).fill(0);let covered=0,l=0,best=[events[0][0],events[events.length-1][0]];for(let r=0;r<events.length;r++){if(counts[events[r][1]]++===0)covered++;while(covered===lists.length){const low=events[l][0],high=events[r][0];if(high-low<best[1]-best[0]||(high-low===best[1]-best[0]&&low<best[0]))best=[low,high];if(--counts[events[l++][1]]===0)covered--;}}return best;
}

